import { ReactNode, FC } from 'react';

interface SkeletonProps {
    /** 是否显示加载中 */
    loading?: boolean;
    /** 是否显示动画 */
    animated?: boolean;
    /** 段落行数 */
    rows?: number;
    /** 是否显示头像占位 */
    avatar?: boolean;
    /** 头像形状 */
    avatarShape?: 'circle' | 'square';
    /** 头像尺寸 (rpx) */
    avatarSize?: number;
    /** 是否显示标题占位 */
    title?: boolean;
    /** 标题宽度 */
    titleWidth?: string | number;
    /** 自定义段落宽度 */
    rowsWidth?: (string | number)[];
    /** 子元素（加载完成后显示） */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface SkeletonBlockProps {
    /** 宽度 */
    width?: string | number;
    /** 高度 */
    height?: string | number;
    /** 是否圆形 */
    round?: boolean;
    /** 是否显示动画 */
    animated?: boolean;
    /** 自定义类名 */
    className?: string;
}

declare const SkeletonBlock: FC<SkeletonBlockProps>;
type SkeletonComponent = FC<SkeletonProps> & {
    Block: FC<SkeletonBlockProps>;
};
declare const Skeleton: SkeletonComponent;

export { Skeleton, SkeletonBlock, Skeleton as default };
export type { SkeletonBlockProps, SkeletonProps };
